package com.example.urlshortener;
import com.example.urlshortener.orchestrator.*; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class WorkflowEngineTest {
 private WorkflowEngine engine(){return new WorkflowEngine(new ApprovalGate(),new PolicyGuard(),new AuditTrail(),new WorkflowMetrics(new SimpleMeterRegistry()));}
 @Test void pausesForApprovalThenCompletes(){var e=engine();Agent ok=new Agent(){public String name(){return "ok";}public AgentResult execute(ExecutionContext c){return AgentResult.ok("ok",Map.of());}};var tasks=List.of(new WorkflowTask("REQ","Requirement",List.of(),false,1,ok,()->{}),new WorkflowTask("IMPL","Implementation",List.of("REQ"),true,1,ok,()->{}));String id=e.create(WorkflowScenario.GREENFIELD,"x",tasks);assertEquals(WorkflowStatus.WAITING_FOR_APPROVAL,e.execute(id));e.approve(id,"IMPL");assertEquals(WorkflowStatus.COMPLETED,e.execute(id));}
 @Test void boundedRetryCanRecover(){var e=engine();int[] n={0};Agent flaky=new Agent(){public String name(){return "flaky";}public AgentResult execute(ExecutionContext c){if(n[0]++==0)throw new RuntimeException("temporary");return AgentResult.ok("recovered",Map.of());}};var tasks=List.of(new WorkflowTask("T","Testing",List.of(),false,2,flaky,()->{}));String id=e.create(WorkflowScenario.GREENFIELD,"x",tasks);assertEquals(WorkflowStatus.COMPLETED,e.execute(id));assertEquals(2,e.get(id).tasks().get("T").attempts());}
 @Test void rejectsCycle(){var e=engine();Agent ok=new Agent(){public String name(){return "ok";}public AgentResult execute(ExecutionContext c){return AgentResult.ok("ok",Map.of());}};var tasks=List.of(new WorkflowTask("A","A",List.of("B"),false,1,ok,()->{}),new WorkflowTask("B","B",List.of("A"),false,1,ok,()->{}));assertThrows(IllegalArgumentException.class,()->e.create(WorkflowScenario.GREENFIELD,"x",tasks));}
}